import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"87. 将 C 与其他语言结合使用 (FFI)","description":"The Little Book of C 中文版 — 87. 将 C 与其他语言结合使用 (FFI)","frontmatter":{"title":"87. 将 C 与其他语言结合使用 (FFI)","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 87. 将 C 与其他语言结合使用 (FFI)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":87,"sidebarWeight":87,"alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/087-Using C with Other Languages (FFI)","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/087-Using C with Other Languages (FFI)"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/087-Using C with Other Languages (FFI).md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/087-Using C with Other Languages (FFI).md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/09-可移植与现代 C/087-Using C with Other Languages (FFI).md"};function i(l,a,o,c,d,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/087-Using C with Other Languages (FFI))</p><p>C 通常被称为通用汇编语言，几乎所有现代语言都可以调用它。这是通过外部函数接口 (FFI) 实现的，它定义了不同语言如何与 C 代码交互。</p><p>在本节中，您将学习如何将 C 函数公开给 Python、Rust 和 Go，以及如何在 C 中调用这些语言的函数。</p><h4 id="步骤-1-什么是-ffi" tabindex="-1">步骤 1. 什么是 FFI？ <a class="header-anchor" href="#步骤-1-什么是-ffi" aria-label="Permalink to &quot;步骤 1. 什么是 FFI？&quot;">​</a></h4><p>FFI（外部函数接口）是一个桥梁，允许用一种语言编写的程序使用另一种语言编写的代码。</p><p>为什么 FFI 很重要：</p><ul><li>重用快速、低级 C 库（例如 OpenSSL、SQLite）。</li><li>将 C 模块集成到 Python 或 Go 等高级语言中。</li><li>扩展现有程序而无需重写所有内容。</li><li>将系统级控制与生产力相结合。</li></ul><h4 id="步骤-2-基础-c-abi" tabindex="-1">步骤 2. 基础：C ABI <a class="header-anchor" href="#步骤-2-基础-c-abi" aria-label="Permalink to &quot;步骤 2. 基础：C ABI&quot;">​</a></h4><p>ABI（应用程序二进制接口）定义了函数调用、参数和数据结构在内存中的表示方式。 FFI 之所以有效，是因为 C 具有稳定且简单的 ABI。</p><p>规则包括：</p><ul><li>参数如何传递（寄存器或堆栈）。</li><li>如何处理返回值。</li><li>数据类型如何在内存中对齐。</li></ul><p>这就是为什么几乎每种语言都提供了一种“讲”C ABI 的方法。</p><h4 id="步骤-3-将-c-函数公开给其他语言" tabindex="-1">步骤 3. 将 C 函数公开给其他语言 <a class="header-anchor" href="#步骤-3-将-c-函数公开给其他语言" aria-label="Permalink to &quot;步骤 3. 将 C 函数公开给其他语言&quot;">​</a></h4><p>您可以通过将 C 函数标记为可由其他语言调用<code>extern &quot;C&quot;</code>（如果编译为 C++）或只是常规 C 函数。</p><p>小代码：共享 C 库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file: mathlib.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int a, int b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int multiply(int a, int b) {</span></span>
<span class="line"><span>    return a * b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>将其编译成共享库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -shared -fPIC -o libmathlib.so mathlib.c</span></span></code></pre></div><p>这创建了一个<code>.so</code>（Linux）或<code>.dll</code>（Windows）或<code>.dylib</code>(macOS) 文件，您可以加载其他语言版本。</p><h4 id="步骤-4-在-python-中使用-c-ctypes" tabindex="-1">步骤 4. 在 Python 中使用 C (ctypes) <a class="header-anchor" href="#步骤-4-在-python-中使用-c-ctypes" aria-label="Permalink to &quot;步骤 4. 在 Python 中使用 C (ctypes)&quot;">​</a></h4><p>Python可以直接调用C函数<code>ctypes</code>模块。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import ctypes</span></span>
<span class="line"><span>lib = ctypes.CDLL(&quot;./libmathlib.so&quot;)</span></span>
<span class="line"><span>print(lib.add(2, 3))</span></span>
<span class="line"><span>print(lib.multiply(4, 5))</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5</span></span>
<span class="line"><span>20</span></span></code></pre></div><p>Python 自动转换标准类型 (<code>int</code>,<code>float</code>,<code>char *</code>) 到 C 等价物。</p><p>对于更复杂的类型，您可以定义<code>ctypes.Structure</code>与您的 C 结构相匹配的类。</p><h4 id="步骤-5-在-rust-中使用-c" tabindex="-1">步骤 5. 在 Rust 中使用 C <a class="header-anchor" href="#步骤-5-在-rust-中使用-c" aria-label="Permalink to &quot;步骤 5. 在 Rust 中使用 C&quot;">​</a></h4><p>Rust 有一个内置的<code>extern &quot;C&quot;</code>FFI 的封锁。</p><p>生锈示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#[link(name = &quot;mathlib&quot;)]</span></span>
<span class="line"><span>extern &quot;C&quot; {</span></span>
<span class="line"><span>    fn add(a: i32, b: i32) -&gt; i32;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>fn main() {</span></span>
<span class="line"><span>    unsafe {</span></span>
<span class="line"><span>        println!(&quot;{}&quot;, add(2, 3));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rustc main.rs -L .</span></span></code></pre></div><p>Rust 强制执行<code>unsafe</code>因为它无法验证 C 函数内部发生了什么。</p><h4 id="步骤-6-在-go-中使用-c" tabindex="-1">步骤 6. 在 Go 中使用 C <a class="header-anchor" href="#步骤-6-在-go-中使用-c" aria-label="Permalink to &quot;步骤 6. 在 Go 中使用 C&quot;">​</a></h4><p>Go 使用<code>import &quot;C&quot;</code>无缝 C 集成指令。</p><p>去示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*</span></span>
<span class="line"><span>#include &quot;mathlib.c&quot;</span></span>
<span class="line"><span>*/</span></span>
<span class="line"><span>import &quot;C&quot;</span></span>
<span class="line"><span>import &quot;fmt&quot;</span></span>
<span class="line"><span>func main() {</span></span>
<span class="line"><span>    fmt.Println(C.add(2, 3))</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go run main.go</span></span></code></pre></div><p>Go 将在幕后编译您的 C 代码并自动链接它。</p><h4 id="步骤-7-从-c-调用外部代码" tabindex="-1">步骤 7. 从 C 调用外部代码 <a class="header-anchor" href="#步骤-7-从-c-调用外部代码" aria-label="Permalink to &quot;步骤 7. 从 C 调用外部代码&quot;">​</a></h4><p>您也可以采取另一种方式，在 C 中调用另一种语言的函数。</p><p>示例：C 调用 Python</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;Python.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Py_Initialize();</span></span>
<span class="line"><span>    PyRun_SimpleString(&quot;print(&#39;Hello from Python in C!&#39;)&quot;);</span></span>
<span class="line"><span>    Py_Finalize();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -o main $(python3-config --cflags --ldflags)</span></span></code></pre></div><p>这会在您的 C 程序中嵌入一个 Python 解释器，对于脚本编写或 AI 集成来说非常强大。</p><h4 id="步骤-8-跨语言的数据结构" tabindex="-1">步骤 8. 跨语言的数据结构 <a class="header-anchor" href="#步骤-8-跨语言的数据结构" aria-label="Permalink to &quot;步骤 8. 跨语言的数据结构&quot;">​</a></h4><p>FFI 最适合简单的、C 兼容类型：</p><p>-<code>int</code>,<code>double</code>,<code>char *</code>和平面结构。避免使用 C++ 类、指向复杂结构的指针或可变长度数组，它们通常不能干净地转换。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    int id;</span></span>
<span class="line"><span>    double score;</span></span>
<span class="line"><span>} Record;</span></span></code></pre></div><p>您可以从 Python 轻松使用此结构（<code>ctypes.Structure</code>) 或 铁锈 (<code>#[repr(C)] struct</code>).</p><h4 id="步骤-9-内存所有权规则" tabindex="-1">步骤 9. 内存所有权规则 <a class="header-anchor" href="#步骤-9-内存所有权规则" aria-label="Permalink to &quot;步骤 9. 内存所有权规则&quot;">​</a></h4><p>始终定义谁分配内存和谁释放内存。</p><p>如果 C 分配了一些东西：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char* greet(void) {</span></span>
<span class="line"><span>    char* s = malloc(32);</span></span>
<span class="line"><span>    sprintf(s, &quot;Hello from C!&quot;);</span></span>
<span class="line"><span>    return s;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后调用者（例如Python）必须调用<code>free()</code>通过 FFI 以避免泄漏。永远不要假设另一种语言的垃圾收集器会清理 C 内存。</p><h4 id="步骤-10-微小代码-c-共享库-python" tabindex="-1">步骤 10. 微小代码：C 共享库 + Python <a class="header-anchor" href="#步骤-10-微小代码-c-共享库-python" aria-label="Permalink to &quot;步骤 10. 微小代码：C 共享库 + Python&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// greet.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>char* greet(const char* name) {</span></span>
<span class="line"><span>    static char buf[64];</span></span>
<span class="line"><span>    snprintf(buf, sizeof(buf), &quot;Hello, %s!&quot;, name);</span></span>
<span class="line"><span>    return buf;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -shared -fPIC -o libgreet.so greet.c</span></span></code></pre></div><p>Python：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import ctypes</span></span>
<span class="line"><span>lib = ctypes.CDLL(&quot;./libgreet.so&quot;)</span></span>
<span class="line"><span>lib.greet.restype = ctypes.c_char_p</span></span>
<span class="line"><span>print(lib.greet(b&quot;World&quot;))</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, World!</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>FFI 将 C 语言变成了软件世界的基础，您的 C 代码可以为用任何语言编写的系统提供动力。这就是数据库、操作系统内核和人工智能框架跨生态系统公开 API 的方式。了解 FFI 意味着您可以构建语言桥梁，而不仅仅是程序。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个简单的 C 库（数学、字符串或排序）。</li><li>使用Python加载它<code>ctypes</code>并调用它的函数。</li><li>使用 Rust 重用相同的库<code>extern &quot;C&quot;</code>.</li><li>在 C 中嵌入 Python 作为脚本层。</li><li>考虑哪一方应该拥有和释放内存。</li></ol><p>接下来，您将探索更安全的替代方案和现代 C 功能、边界检查、静态断言以及使 C 代码更可靠的方法。</p>`,71)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
